<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { NAlert, NButton, NCheckbox, NCollapse, NCollapseItem, NForm, NFormItem, NInputNumber, NModal, NSelect, NTag } from 'naive-ui';
import BudgetReservation from './BudgetReservation.vue';
import { budgetUsed, unknownReservations, reservationValid } from '../lib/budget.ts';
import type { CallRecord, StudioOperation, GenerationRecord, Project, ProviderSummary, Reservation, Shot } from '../types.ts';
const props = defineProps<{ show: boolean; project: Project; shots: Shot[]; boardRevision: number; providers: ProviderSummary[]; calls: CallRecord[]; generations: GenerationRecord[]; studioOperations: StudioOperation[]; disabled: boolean }>();
const emit = defineEmits<{ 'update:show': [value: boolean]; submit: [input: { providerId: string; reservation: Reservation; clientRequestId: string; expectedProviderUpdatedAt: string }]; settings: [] }>();
const providerId = ref<string | null>(null);
const acknowledged = ref(false);
const independentAcknowledged = ref(false);
const operationId = ref('');
const reservation = reactive<Reservation>({ currency: 'USD', amount: 0.1, singleLimit: 1, projectLimit: 5 });
const options = computed(() => props.providers.filter(provider => provider.kind === 'chat-completions').map(provider => ({ value: provider.id, label: `${provider.label} · ${provider.model}` })));
const provider = computed(() => props.providers.find(item => item.id === providerId.value));
const unresolved = computed(() => unknownReservations([...props.calls, ...props.generations, ...props.studioOperations]));
const used = computed(() => budgetUsed([...props.calls, ...props.generations, ...props.studioOperations], reservation.currency));
const valid = computed(() => Boolean(provider.value && props.project.brief.trim() && acknowledged.value && (!unresolved.value || independentAcknowledged.value) && reservationValid(reservation, used.value)));
watch(() => props.show, show => { if (show) { acknowledged.value = false; independentAcknowledged.value = false; operationId.value = crypto.randomUUID(); if (!options.value.some(option => option.value === providerId.value)) providerId.value = options.value[0]?.value || null; } });
watch(() => [props.boardRevision, props.project.revision, providerId.value, provider.value?.updatedAt, reservation.currency, reservation.amount, reservation.singleLimit, reservation.projectLimit], () => { acknowledged.value = false; independentAcknowledged.value = false; operationId.value = crypto.randomUUID(); });
function submit() { if (providerId.value && valid.value && !props.disabled) emit('submit', { providerId: providerId.value, reservation: { ...reservation }, clientRequestId: operationId.value, expectedProviderUpdatedAt: provider.value!.updatedAt }); }
</script>

<template>
  <NModal :show="show" preset="card" title="审阅这次推理请求" class="reasoning-modal" :mask-closable="!disabled" :closable="!disabled" @update:show="emit('update:show', $event)"><p class="dialog-intro">让模型基于创作简报和当前分镜提出修改草稿。最多发送一次请求，项目内容由你审阅后再应用。</p><NForm @submit.prevent="submit"><NFormItem label="推理连接"><NSelect v-model:value="providerId" :options="options" :disabled="disabled" placeholder="选择已保存的推理连接" /></NFormItem><NAlert v-if="!options.length" type="info" :show-icon="false" class="draft-alert">还没有推理连接。<NButton text type="primary" @click="emit('settings')">去设置连接</NButton></NAlert><div v-if="provider" class="reasoning-target"><div class="heading-line"><strong>{{ provider.model }}</strong><NTag size="small" :bordered="false">尚未验证</NTag></div><code>{{ provider.baseUrl }}</code><p>{{ provider.timeoutMs / 1000 }} 秒超时 · 最多 {{ provider.maxOutputTokens }} 输出 tokens · 单次请求</p></div><NCollapse class="reasoning-context"><NCollapseItem title="查看将发送的简报与分镜" name="context"><div class="context-brief"><strong>创作简报</strong><p>{{ project.brief || '（简报为空）' }}</p></div><div v-if="!shots.length" class="context-shot">当前没有镜头，模型可提出新分镜。</div><article v-for="(shot, index) in shots" :key="shot.id" class="context-shot"><h3>{{ String(index + 1).padStart(2, '0') }} · {{ shot.title }}</h3><dl><div><dt>目的</dt><dd>{{ shot.purpose || '（留空）' }}</dd></div><div><dt>画面</dt><dd>{{ shot.description || '（留空）' }}</dd></div><div><dt>动作</dt><dd>{{ shot.action || '（留空）' }}</dd></div><div><dt>时长 / 素材方式</dt><dd>{{ shot.durationMs / 1000 }} 秒 · {{ shot.mode }}</dd></div><div><dt>字幕</dt><dd>{{ shot.caption || '（留空）' }}</dd></div><div><dt>参考素材 ID</dt><dd>{{ shot.referenceArtifactIds.join('、') || '无' }}</dd></div></dl></article><p class="panel-footnote">分镜版本 r{{ boardRevision }}。请求包含镜头字段与版本标识，不上传本地媒体文件。</p></NCollapseItem></NCollapse><BudgetReservation :model-value="reservation" :calls="calls" :generations="generations" :studio-operations="studioOperations" :disabled="disabled" @update:model-value="Object.assign(reservation, $event)" /><NCheckbox v-if="unresolved" v-model:checked="independentAcknowledged" class="reasoning-acknowledgement" :disabled="disabled">我确认发起独立新请求，旧调用继续保留预留并等待核对。</NCheckbox><NCheckbox v-model:checked="acknowledged" class="reasoning-acknowledgement" :disabled="disabled || !provider">我已核对发送内容、连接和本地费用预留。</NCheckbox><div class="dialog-actions"><NButton :disabled="disabled" @click="emit('update:show', false)">返回编辑</NButton><NButton type="primary" attr-type="submit" :loading="disabled" :disabled="disabled || !valid">提交一次请求</NButton></div></NForm></NModal>
</template>
